effect.shader:
float rand(vec2 co) {
return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}
void main() {
vec2 uv = acScreenNorm;
float time = acTime * max(speed, 0.01);
float noise = rand(vec2(floor(uv.y * 20.0), floor(time * 10.0)));
float glitchLine = step(0.95 - (intensity * 0.1), noise);
vec2 offset = vec2(glitchLine * (rand(vec2(time)) - 0.5) * intensity * 0.1, 0.0);
float r = texture2DCv(inputImg.texture, uv + offset + vec2(rgbSplit * intensity, 0.0)).r;
float g = texture2DCv(inputImg.texture, uv + offset).g;
float b = texture2DCv(inputImg.texture, uv + offset - vec2(rgbSplit * intensity, 0.0)).b;
vec3 col = vec3(r, g, b);
if (scanlines > 0.5) {
float scanline = sin(uv.y * acScreenSize.y * 3.14159 * 2.0) * 0.04;
col -= scanline;
}
gl_FragColor = vec4(col, texture2DCv(inputImg.texture, uv).a);
}
